      "cites": ["queue-master-L00030", "queue-master-L00036", "queue-master-L0003b", "queue-master-L0003c"]
    },
    {
      "claim": "queue-master's loss of serving capacity causes it to return 503 Service Unavailable or not respond in time to orders requests.",
      "status": "uncertain",
      "cites": ["orders-L00001", "orders-L00002", "orders-L0006e", "orders-L00070"]
    },
    {
      "claim": "Orders calls to queue-master fail with 503 or timeout, causing orders to throw IllegalStateException and return 500 to front-end.",
      "status": "confirmed",
      "cites": ["orders-L00001", "orders-L00002", "orders-L0006e", "orders-L00070"]
    },
    {
      "claim": "Front-end receives 500 errors from orders and surfaces them to users as 'Unable to create order due to timeout from one of the services.'",
      "status": "confirmed",
      "cites": ["front-end-L0000b", "front-end-L00738", "front-end-L00776"]
    }
